INSERT INTO questions (id, question_group_id, question_number, question_text_en, explanation_vi, question_text_vi)
VALUES
  (1, 1, 1, NULL, 'Trong hình, người phụ nữ đang ngồi tại một chiếc bàn gỗ ngoài trời và đang ăn, điều này phù hợp với mô tả ''She''s eating in a picnic area'' (Cô ấy đang ăn trong khu vực dã ngoại). Các phương án còn lại không mô tả đúng hành động của người phụ nữ trong ảnh.', ''),
  (2, 2, 2, NULL, NULL, NULL),
  (3, 3, 3, NULL, NULL, NULL),
  (4, 4, 4, NULL, NULL, NULL),
  (5, 5, 5, NULL, NULL, NULL),
  (6, 6, 6, NULL, NULL, NULL),
  (7, 7, 7, NULL, 'Câu hỏi bắt đầu bằng ''How old'' (bao nhiêu tuổi/bao lâu), vì vậy đáp án B ''About 10 years old'' (Khoảng 10 năm tuổi) là câu trả lời phù hợp nhất về mặt thông tin.', NULL),
  (8, 8, 8, NULL, NULL, NULL),
