INSERT INTO questions (id, question_group_id, question_number, question_text_en, explanation_vi, question_text_vi)
VALUES
  (201, 104, 1, NULL, 'Trong hình, người phụ nữ đang thực hiện hành động cắm phích cắm của dây điện vào ổ cắm trên tường. Do đó, đáp án A ''She''s inserting a cord into an outlet'' (Cô ấy đang cắm dây điện vào ổ cắm) là mô tả chính xác nhất cho hành động này.', ''),
  (202, 105, 2, NULL, 'Trong ảnh, người phụ nữ đang đặt một chiếc gối lên ghế sofa ngoài trời. Do đó, câu B ''A pillow is being arranged on a seat'' (Một chiếc gối đang được sắp xếp trên ghế) là mô tả chính xác nhất cho hành động đang diễn ra.', ''),
  (203, 106, 3, NULL, NULL, NULL),
  (204, 107, 4, NULL, 'Trong hình, chúng ta có thể thấy một đống gỗ lớn được xếp chồng lên nhau ở gần hàng rào phía sau sân. Do đó, câu D ''Wood is piled near a fence'' (Gỗ được chất đống gần hàng rào) là mô tả chính xác nhất cho hình ảnh này. Các phương án khác không chính xác vì: A (người đàn ông đang bê giá đỡ, không phải đang chặt gỗ), B (không thấy lá cây rải rác trên cỏ), và C (người đàn ông đang đứng ở cửa ra vào, không phải đang đóng cửa sổ).', ''),
  (205, 108, 5, NULL, 'Đáp án đúng là C vì trong hình ảnh, chúng ta có thể thấy các gian hàng (tents) đã được dựng sẵn tại một khu vực trông giống như bãi đỗ xe (parking area). Các phương án khác không chính xác: A sai vì mọi người đang ở ngoài trời chứ không phải trong sảnh (lobby); B sai vì không có hành động cho hàng hóa vào túi mua sắm đang diễn ra; D sai vì các mái che đã được dựng xong từ trước, không có ai đang thực hiện hành động dựng mái che.', ''),
  (206, 109, 6, NULL, '', ''),
  (207, 110, 7, NULL, 'Câu hỏi bắt đầu bằng ''Have...'' (đã... chưa?), đây là câu hỏi dạng Yes/No. Đáp án A ''No, not yet'' (Chưa, vẫn chưa) là câu trả lời trực tiếp và phù hợp nhất với nội dung câu hỏi về việc các máy móc đã được làm sạch hay chưa.', ''),
  (208, 111, 8, NULL, 'Câu hỏi bắt đầu bằng ''How much'' (bao nhiêu) để hỏi về số lượng hoặc mức độ. Đáp án A ''About 10 percent'' (Khoảng 10 phần trăm) là câu trả lời phù hợp nhất cho câu hỏi về mức tăng ngân sách. Đáp án B trả lời cho câu hỏi về thời gian (How long), và đáp án C trả lời cho câu hỏi về địa điểm (Where).', ''),
  (209, 112, 9, NULL, '', NULL),
  (210, 113, 10, NULL, 'Câu hỏi bắt đầu bằng ''Aren''t you...'' (Bạn không định... sao?), đây là một câu hỏi xác nhận. Đáp án B ''I already scheduled one'' (Tôi đã đặt lịch hẹn rồi) là câu trả lời trực tiếp và hợp lý nhất cho câu hỏi về việc đặt lịch hẹn khám mắt.', NULL),
  (211, 114, 11, NULL, 'Người nói đưa ra ý định sửa máy in. Đáp án C là phản hồi hợp lý nhất vì nó đặt câu hỏi nghi vấn về khả năng sửa chữa của chiếc máy đó, phù hợp với ngữ cảnh của câu đề bài.', NULL),
  (212, 115, 12, NULL, NULL, NULL),
  (213, 116, 13, NULL, 'Câu hỏi bắt đầu bằng ''Has'' (dạng câu hỏi Yes/No) về việc cuộc họp đã được đổi lịch chưa. Đáp án B là phản hồi phù hợp nhất vì xác nhận việc đổi lịch và cung cấp thông tin thời gian mới (ngày mai).', NULL),
  (214, 117, 14, NULL, 'Câu hỏi bắt đầu bằng ''Why don''t we...'' là một lời đề nghị. Đáp án A ''Sure, we have time for that'' (Chắc chắn rồi, chúng ta có thời gian cho việc đó) là phản hồi phù hợp nhất để đồng ý với lời đề nghị ghé qua căng tin.', NULL),
  (215, 118, 15, NULL, 'Câu hỏi hỏi về trải nghiệm đối với món mì pasta ("Bạn đã thử món mì pasta nổi tiếng của chúng tôi chưa?"). Đáp án B ("Vâng, nó rất ngon") là câu trả lời hợp lý nhất vì nó trực tiếp phản hồi về trải nghiệm thưởng thức món ăn đó.', NULL),
  (216, 119, 16, NULL, 'Câu hỏi bắt đầu bằng ''Who'' (Ai), hỏi về danh tính của người biểu diễn mở màn. Đáp án B ''A jazz singer from France'' (Một ca sĩ nhạc jazz đến từ Pháp) là câu trả lời phù hợp nhất để xác định danh tính người đó.', NULL),
  (217, 120, 17, NULL, 'Câu hỏi bắt đầu bằng ''When'' (Khi nào) để hỏi về thời gian. Đáp án A cung cấp thông tin về thời gian (thứ Sáu tuần trước) nên là câu trả lời phù hợp nhất. Đáp án B nói về tính năng sản phẩm, đáp án C trả lời cho câu hỏi về địa điểm (Where).', NULL),
  (218, 121, 18, NULL, 'Câu hỏi đề cập đến việc cập nhật trang web không thành công. Đáp án C là phản hồi hợp lý nhất vì người nghe đề nghị người nói gửi các thay đổi cần thiết để họ thực hiện giúp.', NULL),
  (219, 122, 19, NULL, NULL, NULL),
  (220, 123, 20, NULL, NULL, NULL),
  (221, 124, 21, NULL, NULL, NULL),
  (222, 125, 22, NULL, NULL, NULL),
  (223, 126, 23, NULL, NULL, NULL),
  (224, 127, 24, NULL, NULL, NULL),
  (225, 128, 25, NULL, NULL, NULL),
  (226, 129, 26, NULL, NULL, NULL),
  (227, 130, 27, NULL, NULL, NULL),
  (228, 131, 28, NULL, NULL, NULL),
  (229, 132, 29, NULL, NULL, NULL),
  (230, 133, 30, NULL, NULL, NULL),
  (231, 134, 31, NULL, NULL, NULL),
  (232, 135, 32, 'Where does the conversation most likely take place?', 'Dựa vào các từ khóa như ''docking at the port'' (cập cảng) và ''captain'' (thuyền trưởng), có thể suy ra cuộc hội thoại diễn ra trên một con tàu.', 'Cuộc hội thoại có khả năng diễn ra ở đâu?'),
  (233, 135, 33, 'What caused a delay?', 'Người phụ nữ nói rằng họ phải đổi hướng ''to avoid a storm'' (để tránh bão), điều này dẫn đến việc tàu bị trễ lịch trình.', 'Điều gì đã gây ra sự chậm trễ?'),
  (234, 135, 34, 'What will the man do next?', 'Người phụ nữ yêu cầu người đàn ông thực hiện các vòng kiểm tra buổi sáng, bắt đầu bằng việc ''checking the machinery in the engine room'' (kiểm tra máy móc trong phòng máy), và người đàn ông đồng ý sẽ đến đó ngay.', 'Người đàn ông sẽ làm gì tiếp theo?'),
  (235, 136, 35, 'Where does the woman most likely work?', 'Người đàn ông đến để đặt lịch tập cá nhân (personal training sessions) và hỏi về việc đăng ký hội viên (membership), điều này cho thấy họ đang ở một trung tâm thể hình.', 'Người phụ nữ có khả năng làm việc ở đâu?'),
  (236, 136, 36, 'What does the man ask about?', 'Người đàn ông đề cập đến chương trình ưu đãi trên mạng: ''giảm 50 phần trăm phí hội viên tháng đầu tiên'' (fifty percent off the first month''s membership), đây chính là một khoản giảm giá.', 'Người đàn ông hỏi về điều gì?'),
  (237, 136, 37, 'What will the woman do next?', 'Ở cuối đoạn hội thoại, người phụ nữ nói: ''let me show you around our facility'' (để tôi dẫn anh tham quan cơ sở của chúng tôi), nghĩa là cô ấy sẽ dẫn người đàn ông đi tham quan.', 'Người phụ nữ sẽ làm gì tiếp theo?'),
  (238, 137, 38, 'Who most likely are the speakers?', 'Dựa vào nội dung đoạn hội thoại, hai người đang thảo luận về việc phục chế một bức tranh phong cảnh thời Phục hưng. Do đó, họ là những người phục chế tác phẩm nghệ thuật (Art restorers).', 'Những người nói có khả năng là ai?'),
  (239, 137, 39, 'What does the woman say she will do?', 'Người phụ nữ nói: ''I''ll begin by investigating the artist''s color palette and style to see how we should repair the damaged areas'' (Tôi sẽ bắt đầu bằng việc điều tra bảng màu và phong cách của họa sĩ để xem chúng ta nên sửa chữa các khu vực bị hư hỏng như thế nào). Vì vậy, cô ấy sẽ điều tra vấn đề (Investigate a problem).', 'Người phụ nữ nói cô ấy sẽ làm gì?'),
  (240, 137, 40, 'Why does the man suggest beginning a project quickly?', 'Người đàn ông nói: ''this would be a stunning piece to unveil at our anniversary dinner in June. And since it''s a big project to finish by then, we should get started right away'' (đây sẽ là một tác phẩm tuyệt đẹp để ra mắt tại bữa tiệc kỷ niệm của chúng ta vào tháng 6. Và vì đây là một dự án lớn cần hoàn thành trước thời điểm đó, chúng ta nên bắt đầu ngay lập tức). Điều này cho thấy một sự kiện quan trọng đang đến gần.', 'Tại sao người đàn ông đề nghị bắt đầu dự án nhanh chóng?'),
  (241, 138, 41, 'What is the woman preparing?', 'Người phụ nữ hỏi Ozan liệu anh ấy có thời gian xem lại ''some slides I''m presenting'' (một vài slide tôi sẽ trình bày) hay không, vì vậy đáp án đúng là A: Một bài thuyết trình bằng slide.', 'Người phụ nữ đang chuẩn bị gì?'),
  (242, 138, 42, 'What kind of business is Smith Incorporated?', 'Trong đoạn hội thoại, người phụ nữ nói rằng cô ấy đang trình bày kế hoạch tiếp thị cho ''their chain of bookstores'' (chuỗi nhà sách của họ), vì vậy đáp án đúng là D: Một chuỗi nhà sách.', 'Smith Incorporated là loại hình doanh nghiệp nào?'),
  (243, 138, 43, 'What do the men agree about?', 'Ozan cho rằng khách hàng thích các cuộc họp không trang trọng (informal meetings) và Thilo đồng ý rằng họ thích một cuộc trò chuyện hơn là một bài thuyết trình. Do đó, cả hai người đàn ông đều đồng ý rằng cuộc họp nên mang tính thân mật (casual), đáp án đúng là D.', 'Những người đàn ông đồng ý về điều gì?'),
  (244, 139, 44, 'Why does the woman congratulate the man?', 'Người phụ nữ nói: ''Tôi nghe nói kết quả thí nghiệm của anh tốt hơn mong đợi. Xin chúc mừng.'' Do đó, đáp án đúng là C: Thí nghiệm của anh ấy đã thành công.', 'Tại sao người phụ nữ chúc mừng người đàn ông?'),
  (245, 139, 45, 'What does the man imply when he says, “Esra’s leaving the company next week”?', 'Trước đó, người phụ nữ bảo người đàn ông nộp báo cáo cho giám đốc nghiên cứu là Ezra. Khi người đàn ông nói ''Ezra sẽ rời công ty vào tuần tới'', anh ấy ngụ ý rằng mình sẽ không nộp báo cáo cho cô ấy nữa vì cô ấy không còn làm việc ở đó. Đáp án đúng là B.', 'Người đàn ông ngụ ý gì khi nói “Esra sẽ rời công ty vào tuần tới”?'),
  (246, 139, 46, 'What does the man hope to do next quarter?', 'Người đàn ông nói: ''Tôi chưa bao giờ quản lý toàn bộ một nhóm nghiên cứu. Tôi hy vọng sẽ có chút kinh nghiệm làm việc đó vào quý tới.'' Vì vậy, đáp án đúng là D: Có thêm kinh nghiệm quản lý.', 'Người đàn ông hy vọng sẽ làm gì vào quý tới?'),
  (247, 140, 47, 'Where most likely are the speakers?', 'Người phụ nữ nói: ''Now we''ll move on to a special segment of our news program... Thanks for coming into the studio today, Dhruv!'' (Bây giờ chúng ta sẽ chuyển sang một chuyên mục đặc biệt trong chương trình tin tức... Cảm ơn vì đã đến trường quay hôm nay, Dhruv!). Điều này cho thấy họ đang ở trường quay truyền hình.', 'Những người nói có khả năng đang ở đâu?'),
  (248, 140, 48, 'What does the man say he recently did?', 'Người đàn ông nói: ''I''m excited to tell you about the gym I just opened last month.'' (Tôi rất hào hứng kể cho bạn về phòng gym mà tôi vừa mở tháng trước). Vì vậy, anh ấy đã mở một cơ sở mới.', 'Người đàn ông nói gần đây anh ấy đã làm gì?'),
  (249, 140, 49, 'What does the woman ask the man to talk about?', 'Sau khi người đàn ông giới thiệu về phòng gym, người phụ nữ hỏi: ''How did you get started in this line of work?'' (Anh bắt đầu trong lĩnh vực này như thế nào?). Câu hỏi này yêu cầu người đàn ông chia sẻ về con đường sự nghiệp của mình.', 'Người phụ nữ yêu cầu người đàn ông nói về điều gì?'),
  (250, 141, 50, 'What has the woman been hired to do?', 'Trong đoạn hội thoại, người phụ nữ nói: ''I''m looking forward to writing about Redmond''s initiatives in marine biology'' (Tôi rất mong được viết về các sáng kiến của Redmond trong lĩnh vực sinh học biển). Do đó, cô ấy được thuê để viết các bài báo.', 'Người phụ nữ được thuê để làm gì?'),
  (251, 141, 51, 'According to the director, what is the organization’s goal?', 'Giám đốc nói: ''Public awareness will help us get funding to meet our aim of preserving these ecosystems'' (Nhận thức của công chúng sẽ giúp chúng tôi có được nguồn tài trợ để đạt mục tiêu bảo tồn các hệ sinh thái này). Vì vậy, mục tiêu của tổ chức là bảo vệ môi trường nước (aquatic ecosystems).', 'Theo giám đốc, mục tiêu của tổ chức là gì?'),
  (252, 141, 52, 'What does Roberto say is exciting?', 'Roberto nói: ''And what''s exciting is that we''ve started using drones to photograph the area with the mangroves'' (Và điều thú vị là chúng tôi đã bắt đầu sử dụng máy bay không người lái để chụp ảnh khu vực có rừng ngập mặn). Máy bay không người lái (drones) chính là thiết bị được nhắc đến.', 'Roberto nói điều gì là thú vị?'),
  (253, 142, 53, 'What does the man say about some contacts in China?', 'Người đàn ông nói: ''our research partners in China are off this week for a national holiday'' (các đối tác nghiên cứu của chúng ta ở Trung Quốc đang nghỉ tuần này vì kỳ nghỉ lễ quốc gia). Do đó, đáp án đúng là C.', 'Người đàn ông nói gì về một số liên hệ ở Trung Quốc?'),
  (254, 142, 54, 'What does the woman imply when she says, “we didn’t allocate funds for a project leader”?', 'Khi người phụ nữ chỉ ra rằng ngân sách không phân bổ tiền cho trưởng dự án, cô ấy đang ngụ ý rằng ngân sách hiện tại không đủ để chi trả cho vị trí này, dẫn đến việc không thể thuê trưởng dự án. Đáp án đúng là D.', 'Người phụ nữ ngụ ý gì khi nói “chúng ta đã không phân bổ ngân sách cho một trưởng dự án”?'),
  (255, 142, 55, 'What does the woman say about some travel expenses?', 'Người phụ nữ đề cập đến chuyến đi Singapore để trình bày kết quả và nói: ''We don''t really need to do that'' (Chúng ta thực sự không cần làm việc đó), điều này có nghĩa là chi phí cho chuyến đi này là không cần thiết. Đáp án đúng là A.', 'Người phụ nữ nói gì về một số chi phí đi lại?'),
  (256, 143, 56, 'Where is the woman calling from?', NULL, 'Người phụ nữ đang gọi từ đâu?'),
  (257, 143, 57, 'What is some software being used for?', NULL, 'Một số phần mềm đang được dùng để làm gì?'),
  (258, 143, 58, 'What does the man help the woman do?', NULL, 'Người đàn ông giúp người phụ nữ làm gì?'),
  (259, 144, 59, 'Where are the speakers most likely working?', NULL, 'Những người nói có khả năng đang làm việc ở đâu?'),
  (260, 144, 60, 'What have the speakers been asked to do?', NULL, 'Những người nói đã được yêu cầu làm gì?'),
  (261, 144, 61, 'What does the man offer to do?', NULL, 'Người đàn ông đề nghị làm gì?'),
  (262, 145, 62, 'Why does the man apologize?', NULL, 'Tại sao người đàn ông xin lỗi?'),
  (263, 145, 63, 'According to the woman, why will the speakers be very busy today?', NULL, 'Theo người phụ nữ, tại sao hôm nay họ sẽ rất bận?'),
  (264, 145, 64, 'Look at the graphic. Where will the man go first?', NULL, 'Nhìn vào hình. Người đàn ông sẽ đi đâu trước?'),
  (265, 146, 65, 'Where do the speakers most likely work?', NULL, 'Những người nói có khả năng làm việc ở đâu?'),
  (266, 146, 66, 'What does the woman say will take place next month?', NULL, 'Người phụ nữ nói điều gì sẽ diễn ra vào tháng tới?'),
  (267, 146, 67, 'Look at the graphic. What kind of seedlings will be given away?', NULL, 'Nhìn vào hình. Loại cây con nào sẽ được tặng?'),
  (268, 147, 68, 'Where does the conversation most likely take place?', 'Người đàn ông gọi món ''cà phê đen lớn'' và ''bánh sừng bò trứng phô mai'', đây là những món ăn thường thấy tại một quán cà phê. Do đó, cuộc hội thoại diễn ra tại một quán cà phê.', 'Cuộc hội thoại có khả năng diễn ra ở đâu?'),
  (269, 147, 69, 'Look at the graphic. How much will the man save on his purchase?', 'Trong đoạn hội thoại, người đàn ông nói rằng anh ấy không phải là khách hàng thân thiết (loại trừ phương án 7%) nhưng anh ấy có thẻ ''EasyCash''. Theo hình ảnh cung cấp, việc thanh toán bằng thẻ ''EZ-Cash card'' giúp khách hàng tiết kiệm được 2%.', 'Nhìn vào hình. Người đàn ông sẽ tiết kiệm được bao nhiêu cho món hàng của mình?'),
  (270, 147, 70, 'What does the man say he will do later today?', 'Người đàn ông nói: ''No, I''ll call you later today when I know what everyone wants'' (Không, tôi sẽ gọi lại cho cô sau hôm nay khi tôi biết mọi người muốn gì) để đặt bữa sáng cho nhóm của mình. Vì vậy, anh ấy sẽ gọi điện cho cửa hàng.', 'Người đàn ông nói anh ấy sẽ làm gì vào cuối ngày hôm nay?'),
  (271, 148, 71, 'Who most likely is the speaker?', 'Người nói đề cập đến việc gửi ''earrings and necklaces'' (bông tai và vòng cổ) mà người nghe đã đặt, đồng thời giới thiệu một sản phẩm mới là ''a case for your jewelry'' (hộp đựng trang sức). Do đó, người nói có khả năng nhất là một người làm đồ trang sức (jewelry maker).', 'Người nói có khả năng nhất là ai?'),
  (272, 148, 72, 'Why did the speaker include a special gift?', 'Trong đoạn hội thoại, người nói giải thích: ''Because you''ve been a customer for over 10 years, I''ve also included a special gift'' (Vì bạn đã là khách hàng hơn 10 năm nay, tôi đã gửi kèm một món quà đặc biệt). Điều này cho thấy người nghe là một khách hàng thân thiết (loyal customer).', 'Tại sao người nói lại bao gồm một món quà đặc biệt?'),
  (273, 148, 73, 'Why is the listener asked to return a phone call?', 'Người nói yêu cầu người nghe gọi lại sau khi nhận được hàng vì: ''I''d really like to hear your thoughts on it'' (Tôi rất muốn nghe ý kiến của bạn về sản phẩm này). Điều này tương đương với việc đưa ra phản hồi (give feedback).', 'Tại sao người nghe được yêu cầu gọi lại?'),
  (274, 149, 74, 'What does the listener want to do?', 'Trong đoạn hội thoại, người nói đề cập: ''We received your voicemail about wanting to frame a wedding picture'' (Chúng tôi đã nhận được tin nhắn thoại của bạn về việc muốn đóng khung một bức ảnh cưới). Do đó, đáp án đúng là D.', 'Người nghe muốn làm gì?'),
  (275, 149, 75, 'What does the speaker expect the listener to do on a Web site?', 'Người nói hướng dẫn người nghe: ''You can complete the whole order online, including uploading your photo, selecting a frame, and arranging payment'' (Bạn có thể hoàn tất toàn bộ đơn hàng trực tuyến, bao gồm tải ảnh lên, chọn khung và sắp xếp thanh toán). Vì vậy, người nói mong người nghe đặt hàng trên trang web. Đáp án đúng là B.', 'Người nói mong người nghe làm gì trên trang web?'),
  (276, 149, 76, 'What is included for an extra fee?', 'Người nói cho biết: ''Also, for a small extra cost, we''ll guarantee to replace your frame in case of damage'' (Ngoài ra, với một khoản phí nhỏ bổ sung, chúng tôi sẽ đảm bảo thay khung của bạn trong trường hợp bị hư hại). Việc đảm bảo thay thế khi hư hại tương đương với một chính sách bảo hành. Đáp án đúng là D.', 'Điều gì được bao gồm với một khoản phí bổ sung?'),
  (277, 150, 77, 'Who are the listeners?', 'Dựa vào câu ''Our physical therapy center is known for the excellent care we provide to our patients, and that''s because of you, our staff'', có thể thấy người nghe là đội ngũ nhân viên tại trung tâm vật lý trị liệu, tức là nhân viên chăm sóc sức khỏe.', 'Những người nghe là ai?'),
  (278, 150, 78, 'What has the speaker prepared?', 'Dựa vào câu ''I''ve prepared different types of activities for us to try out'', người nói đã chuẩn bị các hoạt động (activities) để mọi người cùng thử nghiệm.', 'Người nói đã chuẩn bị gì?'),
  (279, 150, 79, 'What does the speaker imply when he says, “I must leave at noon”?', 'Người nói thông báo phải rời đi vào buổi trưa và ngay sau đó nói ''Next week, we''ll try out more of the games'', ngụ ý rằng buổi đào tạo hôm nay sẽ kết thúc sớm và một số nội dung (các trò chơi còn lại) sẽ không được trình bày hết trong hôm nay.', 'Người nói ngụ ý gì khi nói “Tôi phải rời đi lúc giữa trưa”?'),
  (280, 151, 80, 'What is the purpose of the advertisement?', 'Đoạn quảng cáo bắt đầu bằng việc hỏi người nghe có phải là tài xế xe tải không và đề cập rằng công ty đang tìm kiếm tài xế để gia nhập đội ngũ. Do đó, mục đích của quảng cáo là để tuyển dụng nhân viên.', 'Mục đích của quảng cáo là gì?'),
  (281, 151, 81, 'How is the speaker’s company different from its competitors?', 'Người nói khẳng định: ''In fact, we''re the only company in the region that allows employees to determine their own work hours'' (Thực tế, chúng tôi là công ty duy nhất trong khu vực cho phép nhân viên tự quyết định giờ làm việc của mình). Điều này cho thấy sự khác biệt là công ty cung cấp lịch làm việc linh hoạt.', 'Công ty của người nói khác với các đối thủ như thế nào?'),
  (282, 151, 82, 'What does the speaker encourage the listeners to do?', 'Người nói kết thúc bằng câu: ''Please check out our Web site to learn more about our open positions'' (Vui lòng xem trang web của chúng tôi để tìm hiểu thêm về các vị trí đang tuyển). Vì vậy, người nói khuyến khích người nghe tìm thêm thông tin.', 'Người nói khuyến khích người nghe làm gì?'),
  (283, 152, 83, 'What is the message mainly about?', 'Người nói đề cập rằng chương trình truyền hình ''Farmer''s Table'' muốn giới thiệu nhà hàng của họ trong một tập sắp tới và sẽ đến quay phim vào thứ Tư. Do đó, nội dung chính của tin nhắn là về việc quay phim cho một chương trình truyền hình.', 'Tin nhắn chủ yếu nói về điều gì?'),
  (284, 152, 84, 'What does the speaker ask the listener to do on Wednesday?', 'Người nói là bếp trưởng điều hành (executive chef) và được yêu cầu ''come in earlier than usual'' (đến sớm hơn thường lệ) để chuẩn bị và sắp xếp mọi thứ cho buổi quay phim vào thứ Tư.', 'Người nói yêu cầu người nghe làm gì vào thứ Tư?'),
  (285, 152, 85, 'Where will the speaker go next week?', 'Người nói nhắc lại rằng họ dự định sẽ ra khỏi thành phố vào tuần tới để tham dự ''Springdale Pastry and Dessert Festival'' (Lễ hội Bánh ngọt và Tráng miệng Springdale), đây là một lễ hội ẩm thực.', 'Người nói sẽ đi đâu vào tuần tới?'),
  (286, 153, 86, 'What is the speaker mainly discussing?', 'Người nói giới thiệu về việc Rockville được chọn làm địa điểm xây dựng nhà máy sản xuất pin xe điện. Do đó, chủ đề chính là về một nhà máy (a factory).', 'Người nói chủ yếu đang thảo luận về điều gì?'),
  (287, 153, 87, 'What does the speaker imply when he says, “No one made any comments”?', 'Người nói đề cập rằng tại cuộc họp lấy ý kiến công chúng, không ai phản đối dự án. Điều này ngụ ý rằng dự án nhận được sự ủng hộ (hoặc ít nhất là không có sự phản đối) từ cộng đồng.', 'Người nói ngụ ý gì khi nói “Không ai đưa ra ý kiến nào”?'),
  (288, 153, 88, 'What can the public view at the city hall building?', 'Trong đoạn cuối, người nói cho biết: ''artist-rendered images of the project are on display at the city hall building'' (các hình ảnh mô phỏng của dự án đang được trưng bày tại tòa thị chính). Vì vậy, công chúng có thể xem các hình ảnh tại đây.', 'Công chúng có thể xem gì tại tòa thị chính?'),
  (289, 154, 89, 'What type of product is being advertised?', NULL, 'Loại sản phẩm nào đang được quảng cáo?'),
  (290, 154, 90, 'What special feature does the speaker emphasize?', NULL, 'Người nói nhấn mạnh tính năng đặc biệt nào?'),
  (291, 154, 91, 'How can the listeners receive a discount?', NULL, 'Người nghe có thể nhận giảm giá bằng cách nào?'),
  (292, 155, 92, 'According to the speaker, what is the purpose of the podcast?', NULL, 'Theo người nói, mục đích của podcast là gì?'),
  (293, 155, 93, 'Why does the speaker say, “this product line will not be available for long”?', NULL, 'Tại sao người nói nói “dòng sản phẩm này sẽ không có sẵn lâu”?'),
  (294, 155, 94, 'According to the speaker, what did Rebecca Murray recently do?', NULL, 'Theo người nói, Rebecca Murray gần đây đã làm gì?'),
  (295, 156, 95, 'Why does the speaker apologize?', NULL, 'Tại sao người nói xin lỗi?'),
  (296, 156, 96, 'According to the speaker, why may some listeners need to see an agent?', NULL, 'Theo người nói, tại sao một số người nghe có thể cần gặp nhân viên?'),
  (297, 156, 97, 'Look at the graphic. When is Train 133 scheduled to arrive at its next stop?', NULL, 'Nhìn vào hình. Tàu 133 dự kiến đến điểm dừng tiếp theo lúc mấy giờ?'),
  (298, 157, 98, 'Who most likely are the listeners?', NULL, 'Những người nghe có khả năng là ai?'),
  (299, 157, 99, 'Look at the graphic. Which of the following companies will be affected by a delay?', NULL, 'Nhìn vào hình. Công ty nào sau đây sẽ bị ảnh hưởng bởi sự chậm trễ?'),
  (300, 157, 100, 'What does the speaker invite the listeners to do?', NULL, 'Người nói mời người nghe làm gì?')
INSERT INTO questions (id, question_group_id, question_number, question_text_en, explanation_vi, question_text_vi)
VALUES
  (301, 158, 101, 'Before operating your handheld device, please ------- the enclosed cable to charge it.', 'Câu này yêu cầu một động từ phù hợp với ngữ cảnh hướng dẫn sử dụng thiết bị. ''Use'' (sử dụng) là lựa chọn hợp lý nhất để kết hợp với ''the enclosed cable'' (dây cáp đi kèm) nhằm mục đích sạc thiết bị. Các từ còn lại không phù hợp về nghĩa trong ngữ cảnh này.', 'Trước khi vận hành thiết bị cầm tay của bạn, vui lòng ------- dây cáp đi kèm để sạc thiết bị.'),
  (302, 159, 102, 'Safile’s new external hard drive can ------- store up to one terabyte of data.', 'Trong câu này, chúng ta cần một trạng từ để bổ nghĩa cho động từ ''store'' (lưu trữ). ''Securely'' (một cách an toàn) là trạng từ phù hợp nhất về mặt ngữ pháp và ngữ nghĩa để mô tả cách thức lưu trữ dữ liệu.', 'Ổ cứng ngoài mới của Safile có thể lưu trữ ------- tới một terabyte dữ liệu.'),
  (303, 160, 103, 'Mr. Peterson will travel ------- the Tokyo Office for the annual meeting.', 'Cấu trúc ''travel to [địa điểm]'' có nghĩa là ''đi đến đâu''. Trong câu này, ông Peterson đi đến văn phòng Tokyo để tham dự cuộc họp, vì vậy giới từ ''to'' là lựa chọn chính xác nhất để chỉ hướng di chuyển.', 'Ông Peterson sẽ đi ------- văn phòng Tokyo để tham dự cuộc họp thường niên.'),
  (304, 161, 104, 'Yong-Soo Cosmetics will not charge for items on back order until ------- have left our warehouse.', 'Chỗ trống cần một đại từ đóng vai trò làm chủ ngữ cho động từ ''have left''. Xét về nghĩa, từ cần điền thay thế cho danh từ số nhiều ''items'' (các mặt hàng) ở phía trước, vì vậy đại từ phù hợp nhất là ''they''.', 'Yong-Soo Cosmetics sẽ không tính phí các mặt hàng đang chờ bổ sung cho đến khi ------- rời khỏi kho của chúng tôi.'),
  (305, 162, 105, 'Our premium day tour takes visitors to historic sites ------- the Aprico River.', 'Câu này cần một giới từ chỉ vị trí phù hợp với ngữ cảnh ''dọc theo con sông''. ''Along'' (dọc theo) là giới từ chính xác nhất để mô tả việc các di tích lịch sử nằm dọc theo dòng sông Aprico.', 'Chuyến tham quan cao cấp trong ngày của chúng tôi đưa du khách đến các di tích lịch sử ------- sông Aprico.'),
  (306, 163, 106, 'Eighty percent of drivers surveyed said they would consider buying a vehicle that runs on -------.', 'Cấu trúc câu cần một danh từ đứng sau giới từ ''on'' để chỉ nguồn nhiên liệu mà xe chạy bằng. ''Electricity'' (danh từ: điện) là lựa chọn phù hợp nhất về mặt ngữ pháp và ngữ nghĩa. Các lựa chọn khác: ''electrically'' (trạng từ), ''electricians'' (danh từ chỉ người - thợ điện), và ''electrify'' (động từ) không phù hợp trong ngữ cảnh này.', 'Tám mươi phần trăm tài xế được khảo sát nói rằng họ sẽ cân nhắc mua một chiếc xe chạy bằng -------.'),
  (307, 164, 107, 'Xinzhe Zu has ------- Petrin Engineering as the vice president of operations.', 'Câu này cần một động từ phù hợp về nghĩa để diễn tả việc một người bắt đầu làm việc tại một công ty. ''Joined'' (gia nhập) là lựa chọn chính xác nhất để điền vào chỗ trống: ''Xinzhe Zu đã gia nhập Petrin Engineering với tư cách là phó chủ tịch phụ trách vận hành''.', 'Xinzhe Zu đã ------- Petrin Engineering với tư cách là phó chủ tịch phụ trách vận hành.'),
  (308, 165, 108, 'Next month, Barder House Books will be holding ------- third author’s hour in Cleveland.', NULL, 'Tháng tới, Barder House Books sẽ tổ chức buổi giao lưu tác giả lần thứ ba của ------- tại Cleveland.'),
  (309, 166, 109, 'Chester’s Tiles ------- expanded to a second location in Turnington.', NULL, 'Chester’s Tiles ------- đã mở rộng sang địa điểm thứ hai ở Turnington.'),
  (310, 167, 110, 'Tabrino’s has ------- increased the number of almonds in the Nut Medley snack pack.', NULL, 'Tabrino’s đã tăng ------- số lượng hạnh nhân trong gói snack Nut Medley.'),
  (311, 168, 111, '------- she travels, Jacintha Flores collects samples of local fabrics and patterns.', NULL, '------- cô ấy đi du lịch, Jacintha Flores đều thu thập các mẫu vải và hoa văn địa phương.'),
  (312, 169, 112, 'Most picture ------- at Glowing Photo Lab go on sale at 3:00 p.m. today.', NULL, 'Hầu hết các ------- ảnh tại Glowing Photo Lab sẽ được giảm giá lúc 3 giờ chiều hôm nay.'),
  (313, 170, 113, 'All students in the business management class hold ------- college degrees.', NULL, 'Tất cả sinh viên trong lớp quản trị kinh doanh đều có bằng đại học -------.'),
  (314, 171, 114, 'We hired Noah Wan of Shengyao Accounting Ltd. ------- our company’s financial assets.', NULL, 'Chúng tôi đã thuê Noah Wan từ Shengyao Accounting Ltd. ------- tài sản tài chính của công ty chúng tôi.'),
  (315, 172, 115, 'Ms. Charisse is taking on a new account ------- she finishes the Morrison project.', NULL, 'Cô Charisse sẽ nhận một tài khoản mới ------- cô ấy hoàn thành dự án Morrison.'),
  (316, 173, 116, 'Cormet Motors’ profits are ------- this year than last year.', NULL, 'Lợi nhuận của Cormet Motors năm nay ------- so với năm ngoái.'),
  (317, 174, 117, 'In its ------- advertising campaign, Jaymor Tools demonstrates how reliable its products are.', NULL, 'Trong chiến dịch quảng cáo ------- của mình, Jaymor Tools chứng minh sản phẩm của họ đáng tin cậy như thế nào.'),
  (318, 175, 118, 'Remember to submit receipts for reimbursement ------- returning from a business trip.', NULL, 'Hãy nhớ nộp hóa đơn để được hoàn tiền ------- trở về từ chuyến công tác.'),
  (319, 176, 119, 'Patrons will be able to access Westside Library’s ------- acquired collection of books on Tuesday.', NULL, 'Độc giả sẽ có thể truy cập bộ sưu tập sách ------- được mua của Thư viện Westside vào thứ Ba.'),
  (320, 177, 120, 'Please ------- any questions about time sheets to Tabitha Jones in the payroll department.', NULL, 'Vui lòng ------- mọi câu hỏi về bảng chấm công đến Tabitha Jones ở phòng tiền lương.'),
  (321, 178, 121, 'Before signing a delivery -------, be sure to double-check that all the items ordered are in the shipment.', NULL, 'Trước khi ký ------- giao hàng, hãy chắc chắn kiểm tra lại rằng tất cả các mặt hàng đã đặt đều có trong lô hàng.'),
  (322, 179, 122, 'Funds have been added to the budget for expenses ------- with the new building.', NULL, 'Ngân sách đã được bổ sung cho các chi phí ------- với tòa nhà mới.'),
  (323, 180, 123, 'Ms. Bernard ------- that a deadline was approaching, so she requested some assistance.', NULL, 'Cô Bernard ------- rằng hạn chót đang đến gần, vì vậy cô ấy đã yêu cầu hỗ trợ.'),
  (324, 181, 124, 'Mr. Moscowitz is ------- that Dr. Tanaka will agree to present the keynote speech at this year’s conference.', NULL, 'Ông Moscowitz ------- rằng Tiến sĩ Tanaka sẽ đồng ý trình bày bài phát biểu chính tại hội nghị năm nay.'),
  (325, 182, 125, 'Two Australian companies are developing new smartphones, but it is unclear ------- phone will become available first.', NULL, 'Hai công ty Úc đang phát triển điện thoại thông minh mới, nhưng vẫn chưa rõ điện thoại ------- sẽ được bán trước.'),
  (326, 183, 126, 'Corners Gym offers its members a free lesson in how to use ------- properly.', NULL, 'Corners Gym cung cấp cho hội viên một buổi học miễn phí về cách sử dụng ------- đúng cách.'),
  (327, 184, 127, '------- the rules, overnight parking is not permitted at the clubhouse facility.', NULL, '------- quy định, việc đỗ xe qua đêm không được cho phép tại khu nhà câu lạc bộ.'),
  (328, 185, 128, 'Once everyone -------, we can begin the conference call.', NULL, 'Khi mọi người -------, chúng ta có thể bắt đầu cuộc gọi hội nghị.'),
  (329, 186, 129, 'Each summer a motivational video that highlights the past year’s ------- is shown to all company employees.', NULL, 'Mỗi mùa hè, một video truyền động lực nêu bật ------- của năm vừa qua được chiếu cho tất cả nhân viên công ty.'),
  (330, 187, 130, 'Employees who wish to attend the retirement dinner ------- Ms. Howell’s 30 years of service should contact Mr. Lee.', NULL, 'Những nhân viên muốn tham dự bữa tối nghỉ hưu ------- 30 năm phục vụ của bà Howell nên liên hệ với ông Lee.'),
  (331, 188, 131, NULL, 'Vị trí cần điền là một tính từ để bổ nghĩa cho danh từ ''order'' (đơn hàng). ''Special'' (tính từ) là từ phù hợp nhất để tạo thành cụm ''special order'' (đơn hàng đặc biệt).', NULL),
  (332, 188, 132, NULL, 'Dựa vào ngữ cảnh câu trước, khách hàng đã đặt mua ''a red oak dining table and six matching chairs'' (một bàn ăn gỗ sồi đỏ và sáu chiếc ghế phù hợp). Đây là các món đồ nội thất, nên ''furniture'' là từ phù hợp nhất.', NULL),
  (333, 188, 133, NULL, 'Cấu trúc ''ask to speak to someone'' (yêu cầu được nói chuyện với ai đó) là cấu trúc cố định. Do đó, ''to speak'' là đáp án chính xác.', NULL),
  (334, 188, 134, NULL, 'Câu này yêu cầu chọn một câu phù hợp để hoàn thành đoạn văn. Sau khi yêu cầu khách hàng gọi điện cho người quản lý giao hàng, câu tiếp theo nên là một thông tin liên quan đến việc sắp xếp công việc. Đáp án A ''He can schedule a convenient time'' (Anh ấy có thể sắp xếp một thời gian thuận tiện) là hợp lý nhất để tiếp nối nội dung về việc sắp xếp giao hàng.', NULL),
  (335, 189, 135, NULL, 'Chỗ trống cần một danh từ để tạo thành cụm danh từ song hành với ''comfort'' (sự thoải mái). ''Safety'' (sự an toàn) là danh từ phù hợp nhất về nghĩa và ngữ pháp để điền vào vị trí này.', NULL),
  (336, 189, 136, NULL, 'Câu trước nói về việc bảo trì và làm sạch, câu sau nói thêm về việc thay thế hệ thống mới. ''Furthermore'' (Hơn nữa) là từ nối phù hợp nhất để bổ sung thêm thông tin cho ý trước đó.', NULL),
  (337, 189, 137, NULL, 'Câu trước đó nói về các kỹ thuật viên có trình độ cao. Câu này cần bổ sung thêm các đặc điểm tích cực khác của họ. Đáp án ''Plus, they are friendly, clean, and knowledgeable'' (Thêm vào đó, họ thân thiện, sạch sẽ và hiểu biết) là phù hợp nhất về ngữ cảnh.', NULL),
  (338, 189, 138, NULL, 'Cấu trúc câu bị động ''...backed by our Keep Cool guarantee'' (được bảo đảm bởi sự bảo hành của Keep Cool) là cấu trúc chính xác. Do đó, ta cần dùng quá khứ phân từ ''backed''.', NULL),
  (339, 190, 139, NULL, NULL, NULL),
  (340, 190, 140, NULL, NULL, NULL),
  (341, 190, 141, NULL, NULL, NULL),
  (342, 190, 142, NULL, NULL, NULL),
  (343, 191, 143, NULL, 'Dựa vào ngữ cảnh của email, người viết đang nói về việc bán các sản phẩm trang sức tại cửa hàng của mình. Do đó, những người mua hàng được gọi là ''customers'' (khách hàng).', NULL),
  (344, 191, 144, NULL, 'Câu trước đó đề cập đến việc khách hàng yêu thích thiết kế và chất lượng tay nghề. Câu tiếp theo cần bổ sung thêm một lý do tích cực khác về sản phẩm, vì vậy ''The reasonable prices also make your pieces a great value'' (Mức giá hợp lý cũng khiến các sản phẩm của bạn rất đáng giá) là lựa chọn phù hợp nhất để duy trì mạch văn.', NULL),
  (345, 191, 145, NULL, 'Người viết muốn ''increase the number of units'' (tăng số lượng đơn hàng), vì vậy từ ''double'' (gấp đôi) là từ phù hợp nhất để thể hiện ý định tăng số lượng đơn hàng cho đợt vận chuyển tháng 9.', NULL),
  (346, 191, 146, NULL, 'Cấu trúc câu là ''serve [someone] very well''. Ở đây người viết đang nói về thỏa thuận độc quyền sẽ có lợi cho cả hai bên (người viết và người nhận), nên đại từ tân ngữ ''us'' (chúng ta) là lựa chọn chính xác.', NULL),
  (347, 192, 147, 'What is true about the Savan Business Center?', 'Đoạn văn có đề cập: ''For small-business owners, it can be a challenge to stand out... The Savan Business Center offers support for business owners who need a boost in doing just that.'' (Đối với các chủ doanh nghiệp nhỏ, việc nổi bật có thể là một thách thức... Trung tâm Kinh doanh Savan cung cấp sự hỗ trợ cho các chủ doanh nghiệp cần sự thúc đẩy để làm điều đó). Do đó, đáp án A là chính xác.', 'Điều gì đúng về Trung tâm Kinh doanh Savan?'),
  (348, 192, 148, 'What is indicated about the webinar?', 'Đoạn văn có đề cập: ''Let us help you get more organized in creating effective and far-reaching social media content. Our latest webinar... will cover topics related to making your business stand out.'' (Hãy để chúng tôi giúp bạn tổ chức tốt hơn trong việc tạo nội dung truyền thông xã hội hiệu quả và có tầm ảnh hưởng sâu rộng. Hội thảo trực tuyến mới nhất của chúng tôi... sẽ bao gồm các chủ đề liên quan đến việc làm cho doanh nghiệp của bạn nổi bật). Do đó, đáp án B là chính xác.', 'Điều gì được cho biết về hội thảo trực tuyến?'),
  (349, 193, 149, 'What is mentioned about Dine Out Darville?', 'Trong đoạn văn có đề cập đến cụm từ ''the weeklong event'' (sự kiện kéo dài một tuần), điều này tương ứng với đáp án A: ''It lasts for one week''.', 'Điều gì được đề cập về Dine Out Darville?'),
  (350, 193, 150, 'What is NOT included in the reduced-price meals?', 'Đoạn văn liệt kê các món bao gồm trong bữa ăn bốn món là: ''a cup of soup, a salad, a main course, and a dessert''. Đồ uống (beverage) không được nhắc đến trong danh sách này, vì vậy đáp án D là đáp án chính xác cho câu hỏi phủ định.', 'Điều gì KHÔNG được bao gồm trong các bữa ăn giảm giá?'),
  (351, 194, 151, 'What does Rainsy LLC do?', 'Dựa vào đoạn văn: ''A data storage and analytics firm... Rainsy helps these businesses manage and understand their customer data.'' (Một công ty lưu trữ và phân tích dữ liệu... Rainsy giúp các doanh nghiệp này quản lý và hiểu dữ liệu khách hàng của họ). Do đó, đáp án A là chính xác.', 'Rainsy LLC làm gì?'),
  (352, 194, 152, 'Who will be based in Dade?', 'Dựa vào đoạn văn: ''...the company’s chief executive officer and chief financial officer will relocate to Dade along with approximately 50 percent of the company’s workforce.'' (Giám đốc điều hành và giám đốc tài chính của công ty sẽ chuyển đến Dade cùng với khoảng 50 phần trăm lực lượng lao động của công ty). Do đó, đáp án C là chính xác.', 'Ai sẽ làm việc tại Dade?'),
  (353, 195, 153, 'What is suggested about the paper Mr. Liu is shopping for?', 'Trong tin nhắn lúc 9:48 A.M., ông Liu nói rằng các loại giấy màu xanh khác có sẵn tại cửa hàng đều là ''darker blue'' (xanh đậm hơn). Điều này ngụ ý rằng loại giấy mà cô Bhat cần (loại giấy mà ông Liu đang tìm mua) có màu xanh nhạt hơn.', 'Điều gì được gợi ý về loại giấy mà ông Liu đang mua?'),
  (354, 195, 154, 'At 9:49 a.m., what does Ms. Bhat most likely mean when she writes, “OK, forget it”?', 'Sau khi ông Liu thông báo rằng loại giấy cô cần đã hết hàng và các lựa chọn thay thế khác thì đắt hơn hoặc không đúng màu, cô Bhat đã viết ''OK, forget it'' và quyết định sẽ tự đặt hàng trực tuyến. Điều này cho thấy cô ấy không muốn ông Liu tiếp tục cố gắng mua giấy tại cửa hàng Biz Plus nữa.', 'Lúc 9:49 sáng, cô Bhat có khả năng muốn nói gì khi viết “OK, forget it”?'),
  (355, 196, 155, 'Why did Ms. Otney write the letter?', NULL, 'Tại sao cô Otney viết lá thư này?'),
  (356, 196, 156, 'What is one thing Ms. Otney requested?', NULL, 'Một điều mà cô Otney đã yêu cầu là gì?'),
  (357, 196, 157, 'In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “This is something I would be happy to arrange.”', NULL, 'Câu sau phù hợp nhất ở vị trí nào trong các vị trí được đánh dấu [1], [2], [3], và [4]? “Đây là điều tôi rất sẵn lòng sắp xếp.”'),
  (358, 197, 158, 'Why most likely was the advertisement created?', 'Quảng cáo nêu rõ ''Take advantage of our limited-time offer: 50% off all eyeglass frames through 30 September'' (Hãy tận dụng ưu đãi có thời hạn của chúng tôi: giảm giá 50% cho tất cả các loại gọng kính đến hết ngày 30 tháng 9). Do đó, mục đích chính là để quảng bá một chương trình giảm giá tạm thời.', 'Quảng cáo này có khả năng được tạo ra để làm gì?'),
  (359, 197, 159, 'What is stated about Claro Vision stores?', 'Trong phần liệt kê các ưu điểm, quảng cáo ghi rõ: ''Free eyeglass fittings and adjustments'' (Miễn phí đo và điều chỉnh kính). Điều này tương ứng với đáp án D.', 'Điều gì được nêu về các cửa hàng Claro Vision?'),
  (360, 197, 160, 'What is stated about vision checkups?', 'Quảng cáo đề cập đến ''Low-cost vision checkups by licensed opticians'' (Kiểm tra thị lực chi phí thấp bởi các chuyên gia khúc xạ được cấp phép). ''Licensed opticians'' tương đương với ''certified professional'' (chuyên gia được chứng nhận).', 'Điều gì được nêu về việc kiểm tra thị lực?'),
  (361, 198, 161, 'What is the purpose of the letter?', NULL, 'Mục đích của lá thư là gì?'),
  (362, 198, 162, 'According to the letter, what must Ms. Balakrishnan pay for each month?', NULL, 'Theo lá thư, cô Balakrishnan phải trả tiền cho gì mỗi tháng?'),
  (363, 198, 163, 'Who most likely is Ms. Tan?', NULL, 'Cô Tan có khả năng là ai?'),
  (364, 199, 164, 'Why did Mr. Hagel write the e-mail?', NULL, 'Tại sao ông Hagel viết email này?'),
  (365, 199, 165, 'What is indicated about Qualiview Ltd.?', NULL, 'Điều gì được cho biết về Qualiview Ltd.?'),
  (366, 199, 166, 'The word “address” in paragraph 2, line 2, is closest in meaning to', NULL, 'Từ “address” trong đoạn 2, dòng 2, gần nghĩa nhất với'),
  (367, 199, 167, 'When is Mr. Hagel available next week?', NULL, 'Khi nào ông Hagel rảnh vào tuần tới?'),
  (368, 200, 168, 'What is mentioned about shipping containers?', NULL, 'Điều gì được đề cập về các container vận chuyển?'),
  (369, 200, 169, 'What does Mr. Lam say is needed to resolve the situation?', NULL, 'Ông Lam nói điều gì là cần thiết để giải quyết tình hình?'),
  (370, 200, 170, 'What type of clothing does Fezker produce?', NULL, 'Fezker sản xuất loại quần áo nào?'),
  (371, 200, 171, 'In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “These markets are supplied using more readily available truck and train transportation.”', NULL, 'Câu sau phù hợp nhất ở vị trí nào trong các vị trí được đánh dấu [1], [2], [3], và [4]? “Các thị trường này được cung cấp hàng bằng vận tải xe tải và tàu hỏa, vốn dễ có sẵn hơn.”'),
  (372, 201, 172, 'In what industry do the writers most likely work?', NULL, 'Những người viết có khả năng làm việc trong ngành nào?'),
  (373, 201, 173, 'Why did Mr. Wendel begin the discussion?', NULL, 'Tại sao ông Wendel bắt đầu cuộc thảo luận?'),
  (374, 201, 174, 'What is indicated about the Riverview project?', NULL, 'Điều gì được cho biết về dự án Riverview?'),
  (375, 201, 175, 'At 7:58 a.m., what does Mr. Zuniga most likely mean when he writes, “Will do”?', NULL, 'Lúc 7:58 sáng, ông Zuniga có khả năng muốn nói gì khi viết “Will do”?'),
  (376, 202, 176, 'What does the e-mail indicate about Karabel Industries ice cream?', NULL, 'Email cho biết điều gì về kem của Karabel Industries?'),
  (377, 202, 177, 'What does Ms. Kerluke state that she wants to do?', NULL, 'Cô Kerluke nói rằng cô ấy muốn làm gì?'),
  (378, 202, 178, 'What is suggested about Fatior Labs?', NULL, 'Điều gì được gợi ý về Fatior Labs?'),
  (379, 202, 179, 'Based on the survey form, what flavor will Karabel Industries most likely make adjustments to?', NULL, 'Dựa trên mẫu khảo sát, Karabel Industries có khả năng sẽ điều chỉnh hương vị nào?'),
  (380, 202, 180, 'What can be concluded about participant number 54?', NULL, 'Có thể kết luận điều gì về người tham gia số 54?'),
  (381, 203, 181, 'According to the Web page, what will the job recipient be able to do?', NULL, 'Theo trang web, người nhận công việc sẽ có thể làm gì?'),
  (382, 203, 182, 'On the Web page, the word “suit” in paragraph 2, line 4, is closest in meaning to', NULL, 'Trên trang web, từ “suit” trong đoạn 2, dòng 4, gần nghĩa nhất với'),
  (383, 203, 183, 'What is indicated about Ms. Smith?', NULL, 'Điều gì được cho biết về cô Smith?'),
  (384, 203, 184, 'According to the letter, what is one of Ms. Smith’s responsibilities at MODA?', NULL, 'Theo lá thư, một trong những trách nhiệm của cô Smith tại MODA là gì?'),
  (385, 203, 185, 'What most likely is Medesheen?', NULL, 'Medesheen có khả năng là gì?'),
  (386, 204, 186, 'Why did Mr. Nakashima send the e-mail?', NULL, 'Tại sao ông Nakashima gửi email?'),
  (387, 204, 187, 'According to the second e-mail, what will Mr. Nakashima receive with his next order?', NULL, 'Theo email thứ hai, ông Nakashima sẽ nhận được gì trong đơn hàng tiếp theo?'),
  (388, 204, 188, 'For what item does Mr. Higgins suggest that Mr. Nakashima select “Recurring Order”?', NULL, 'Ông Higgins gợi ý ông Nakashima chọn “Đơn hàng định kỳ” cho mặt hàng nào?'),
  (389, 204, 189, 'What will Mr. Higgins ask the technical team to look into?', NULL, 'Ông Higgins sẽ yêu cầu đội kỹ thuật xem xét điều gì?'),
  (390, 204, 190, 'What is needed to return an item at a Fowler Office Supplies store?', NULL, 'Cần gì để trả lại một món hàng tại cửa hàng Fowler Office Supplies?'),
  (391, 205, 191, 'What is the purpose of the article?', 'Tiêu đề của bài báo là ''Crawford and Duval Opens Brick-and-Mortar Stores'' (Crawford and Duval mở các cửa hàng truyền thống) và nội dung bài báo nói về việc công ty này đã thành lập bốn cửa hàng tại Hồng Kông. Do đó, mục đích của bài báo là để thông báo việc mở các cửa hàng này.', 'Mục đích của bài báo là gì?'),
  (392, 205, 192, 'What does the Web site indicate about Crawford and Duval?', 'Trong phần nội dung của trang web, câu thứ hai trong đoạn thứ hai nêu rõ: ''Each location has an interior designer on staff'' (Mỗi địa điểm đều có một nhà thiết kế nội thất trong đội ngũ nhân viên). Vì vậy, đáp án đúng là công ty tuyển dụng các nhà thiết kế nội thất.', 'Trang web cho biết điều gì về Crawford and Duval?'),
  (393, 205, 193, 'According to the receipt, what is indicated about the blanket?', 'Trên biên nhận (receipt), mục thứ tư được liệt kê là ''Machine-washable wool blanket'' (Chăn len có thể giặt bằng máy). Điều này cho thấy chiếc chăn có thể được giặt bằng máy.', 'Theo biên nhận, điều gì được cho biết về chiếc chăn?'),
  (394, 205, 194, 'Where most likely did Ms. Fong make her purchase?', 'Bài báo đề cập rằng địa điểm ở Central District có ''an indoor plant department'' (một bộ phận cây trồng trong nhà). Trên biên nhận của cô Fong, cô đã mua ''Aloe plant in a 7.5-litre planter'' (cây lô hội trong chậu 7.5 lít). Vì chỉ có cửa hàng ở Central District mới có bộ phận cây trồng, nên cô Fong đã mua hàng tại cửa hàng này, vốn được mô tả là một cửa hàng bách hóa (department store) trong ngữ cảnh bài báo.', 'Cô Fong có khả năng đã mua hàng ở đâu?'),
  (395, 205, 195, 'What is suggested about Ms. Fong?', 'Trên biên nhận, tổng giá trị đơn hàng là HK$4,500.00 và cô Fong được giảm giá 10% (tương đương HK$450.00). Theo thông tin trên trang web, ''Members of our online Frequent Purchase Club will receive... a 10 percent discount on purchases of HK$500 or more''. Vì cô Fong được giảm 10% cho đơn hàng trên HK$500, nên có thể suy ra cô ấy là thành viên của Câu lạc bộ mua hàng thường xuyên.', 'Điều gì được gợi ý về cô Fong?'),
  (396, 206, 196, 'What does the first Web page indicate about the Scavenger Hunt?', 'Dựa vào trang web đầu tiên, phần mô tả về ''Scavenger Hunt'' ghi rõ: ''Time: 3 hours'' (Thời gian: 3 giờ). Do đó, đáp án đúng là D.', 'Trang web đầu tiên cho biết điều gì về trò Scavenger Hunt?'),
  (397, 206, 197, 'What event is best for a group of more than 200 people?', 'Dựa vào trang web đầu tiên, các giới hạn số lượng người tham gia là: Scavenger Hunt (10-50), Game Day (20-500), Team Painting (6-30), Robot Building (10-30), All Chocolate (8-150). Chỉ có ''Game Day'' là sự kiện duy nhất có thể chứa nhóm hơn 200 người. Do đó, đáp án đúng là A.', 'Sự kiện nào phù hợp nhất cho một nhóm hơn 200 người?'),
  (398, 206, 198, 'What is suggested about Ms. Peterson?', 'Cô Peterson đặt sự kiện vào tháng 10 (''October 15''). Trang web đầu tiên có ghi chú: ''Book an event in October and receive 15 percent off'' (Đặt sự kiện vào tháng 10 và nhận giảm giá 15 phần trăm). Do đó, cô ấy sẽ nhận được giảm giá. Đáp án đúng là B.', 'Điều gì được gợi ý về cô Peterson?'),
  (399, 206, 199, 'What can be concluded about Whitten Tech?', 'Trong đơn yêu cầu, cô Peterson chọn ''Game Day'' là lựa chọn số 1. Tuy nhiên, trong bài đánh giá, Whitten Tech cho biết họ đã thực hiện ''Scavenger Hunt''. Điều này cho thấy họ không thể tổ chức hoạt động lựa chọn đầu tiên của mình. Do đó, đáp án đúng là C.', 'Có thể kết luận điều gì về Whitten Tech?'),
  (400, 206, 200, 'According to the review, what was disappointing about the event?', 'Trong bài đánh giá, khách hàng viết: ''The only downside was that we did not realize how far we would be walking. It would have been helpful to have an idea of the walking distances...'' (Điểm trừ duy nhất là chúng tôi không nhận ra mình sẽ phải đi bộ xa như thế nào. Sẽ hữu ích hơn nếu biết trước về quãng đường đi bộ...). Do đó, đáp án đúng là B.', 'Theo bài đánh giá, điều gì gây thất vọng về sự kiện?')
