VALUES
  (701, 364, 101, '------- your order is being processed, please call customer service with any questions.', NULL, '------- đơn hàng của bạn đang được xử lý, vui lòng gọi cho bộ phận dịch vụ khách hàng nếu có bất kỳ câu hỏi nào.'),
