  (1099, 569, 99, 'Why is a building special?', NULL, 'Tại sao một tòa nhà lại đặc biệt?'),
  (1100, 569, 100, 'Look at the graphic. Which floor of the building is not open yet?', NULL, 'Nhìn vào biểu đồ. Tầng nào của tòa nhà vẫn chưa mở cửa?')
INSERT INTO questions (id, question_group_id, question_number, question_text_en, explanation_vi, question_text_vi)
VALUES
  (1101, 570, 101, 'Mr. Barrientos has worked at the company ------- six years.', NULL, 'Ông Barrientos đã làm việc tại công ty ------- sáu năm.'),
  (1102, 571, 102, 'The staff cafeteria stops ------- lunch at 2:00 P.M.', NULL, 'Quán ăn tự phục vụ cho nhân viên ngừng ------- bữa trưa lúc 2:00 chiều.'),
  (1103, 572, 103, 'The annual report will be ready after ------- make the necessary revisions.', NULL, 'Báo cáo thường niên sẽ sẵn sàng sau khi ------- thực hiện các sửa đổi cần thiết.'),
  (1104, 573, 104, 'Mr. Louden was offered a full-time position at Fortelio Corporation ------- a division manager.', NULL, 'Ông Louden được mời một vị trí toàn thời gian tại Fortelio Corporation ------- một người quản lý bộ phận.'),
  (1105, 574, 105, 'Kennedy Sports will ------- its end-of-season sale through the month of January.', NULL, 'Kennedy Sports sẽ ------- đợt giảm giá cuối mùa qua suốt tháng Một.'),
  (1106, 575, 106, 'Ms. Najjar is going to give a presentation ------- workplace regulations at noon.', NULL, 'Bà Najjar sẽ trình bày một bài thuyết trình ------- quy định nơi làm việc vào buổi trưa.'),
  (1107, 576, 107, 'Mr. Telguld submitted the ------- surveys before the monthly board meeting.', NULL, 'Ông Telguld đã nộp các bản khảo sát ------- trước cuộc họp hội đồng quản trị hàng tháng.'),
  (1108, 577, 108, 'Travel funds are available to student presenters coming to the conference from a significant -------.', NULL, 'Kinh phí đi lại có sẵn cho các sinh viên thuyết trình đến hội nghị từ một ------- đáng kể.'),
  (1109, 578, 109, 'Ms. Okada is ------- a new social media campaign at the request of our office manager.', NULL, 'Bà Okada đang ------- một chiến dịch truyền thông xã hội mới theo yêu cầu của quản lý văn phòng chúng tôi.'),
  (1110, 579, 110, 'The speaker will offer five tips for making wise purchasing -------.', NULL, 'Người diễn giả sẽ đưa ra năm lời khuyên để đưa ra các ------- mua sắm khôn ngoan.'),
  (1111, 580, 111, 'Please log on to your online checking account ------- the next 30 days in order to keep it active.', NULL, 'Vui lòng đăng nhập vào tài khoản séc trực tuyến của bạn ------- 30 ngày tới để giữ cho nó hoạt động.'),
