  (1114, 583, 114, '------- the event organizers'' best efforts, they have been unable to attract enough volunteers this spring.', NULL, '------- những nỗ lực hết sức của ban tổ chức sự kiện, họ đã không thể thu hút đủ tình nguyện viên vào mùa xuân này.'),
  (1115, 584, 115, 'Mr. Perez ------- as an industrial engineer at Gaberly Logistics for almost twenty years.', NULL, 'Ông Perez ------- với tư cách là một kỹ sư công nghiệp tại Gaberly Logistics trong gần hai mươi năm.'),
  (1116, 585, 116, 'Soon after Ms. Manilla was hired, the sales department''s productivity began to increase -------.', NULL, 'Ngay sau khi bà Manilla được thuê, năng suất của bộ phận bán hàng bắt đầu tăng -------.'),
  (1117, 586, 117, 'Small businesses ------- participate in the Get Ahead program will receive marketing tools to help them attract customers.', NULL, 'Các doanh nghiệp nhỏ ------- tham gia chương trình Get Ahead sẽ nhận được các công cụ tiếp thị để giúp họ thu hút khách hàng.'),
  (1118, 587, 118, 'Our copy editors will review the manuscript ------- will not return it until the end of next week.', NULL, 'Các biên tập viên của chúng tôi sẽ xem xét bản thảo ------- sẽ không trả lại nó cho đến cuối tuần tới.'),
  (1119, 588, 119, 'Mira Kumar was probably the ------- of all the interns at Kolbry Media last summer.', NULL, 'Mira Kumar có lẽ là người ------- trong số tất cả các thực tập sinh tại Kolbry Media vào mùa hè năm ngoái.'),
  (1120, 589, 120, 'Orbin''s Fish Company expanded to a total of 26 stores ------- its takeover of a rival chain.', NULL, 'Công ty Cá Orbin đã mở rộng thành tổng cộng 26 cửa hàng ------- việc tiếp quản một chuỗi đối thủ.'),
  (1121, 590, 121, 'Ms. Cartwright told her team members that she wanted to streamline the company''s assembly process -------.', NULL, 'Bà Cartwright nói với các thành viên trong nhóm của mình rằng bà muốn tự ------- hợp lý hóa quy trình lắp ráp của công ty.'),
  (1122, 591, 122, 'Rupert''s Food Service uses ------- technology to track all of its shipments.', NULL, 'Dịch vụ thực phẩm Rupert sử dụng công nghệ ------- để theo dõi tất cả các lô hàng của mình.'),
  (1123, 592, 123, 'Our app includes a ------- so that users can determine whether they are within their budget goals.', NULL, 'Ứng dụng của chúng tôi bao gồm một ------- để người dùng có thể xác định xem họ có nằm trong mục tiêu ngân sách của mình hay không.'),
  (1124, 593, 124, 'To ------- that its facilities are cleaned every day, the Selboa Company has hired more janitors.', NULL, 'Để ------- rằng các cơ sở của mình được làm sạch mỗi ngày, Công ty Selboa đã thuê thêm nhiều lao công.'),
  (1125, 594, 125, 'During his term as a legislator, Jeremy Moran ------- promoted public awareness of the need for infrastructure improvements.', NULL, 'Trong nhiệm kỳ lập pháp của mình, Jeremy Moran đã ------- thúc đẩy nhận thức của công chúng về sự cần thiết phải cải thiện cơ sở hạ tầng.'),
  (1126, 595, 126, 'Pyxie Print''s business is so new that we need to explain the full range of our services to ------- clients.', NULL, 'Công việc kinh doanh của Pyxie Print còn quá mới nên chúng tôi cần giải thích toàn bộ các dịch vụ của mình cho các khách hàng -------.'),
  (1127, 596, 127, 'Phone orders that are ------- to local stores by 11:00 A.M. are eligible for same-day pickup.', NULL, 'Các đơn đặt hàng qua điện thoại được ------- cho các cửa hàng địa phương trước 11:00 sáng sẽ đủ điều kiện để nhận hàng trong ngày.'),
  (1128, 597, 128, 'An Oswald Hardware associate will ------- place an order for customers who need larger quantities than what is in stock.', NULL, 'Một cộng tác viên của Oswald Hardware sẽ ------- đặt hàng cho những khách hàng cần số lượng lớn hơn so với những gì còn trong kho.'),
  (1129, 598, 129, 'Mia Daushvili performed with the Bayhead Orchestra on Monday evening, ------- her virtuosic skills on the piccolo.', NULL, 'Mia Daushvili đã biểu diễn với Dàn nhạc Bayhead vào tối thứ Hai, ------- kỹ năng bậc thầy của cô ấy trên cây sáo piccolo.'),
  (1130, 599, 130, 'When reviewing applicants for the clerk position, Ms. Ng will consider both education and ------- experience.', NULL, 'Khi xem xét các ứng viên cho vị trí nhân viên bán hàng, bà Ng sẽ cân nhắc cả trình độ học vấn và kinh nghiệm -------.'),
